/**
 * The main mobile SIP engine interface.
 */
public protocol AriaMobileEngineProtocol : AnyObject {
    
    /**
     * Accept an incoming call with local SDP answer.
     */
    func acceptIncomingCall(callToken: String, preferredCodecs: [AudioCodec]) throws  -> CallInfo
    
    /**
     * Was this binary built with transcription support?
     *
     * Lets one app package probe at runtime instead of the host guessing from
     * its build flavour.
     */
    func aiAvailable()  -> Bool
    
    func aiCancelDownload(modelId: String) 
    
    /**
     * Returns how many insights were deleted.
     */
    func aiClearInsights()  -> UInt64
    
    func aiDeleteInsight(callId: String)  -> Bool
    
    func aiDeleteModel(modelId: String) throws 
    
    /**
     * Discard a captured call without transcribing it.
     */
    func aiDiscardCapture(callId: String) 
    
    func aiDownloadProgress(modelId: String)  -> AiDownloadProgress?
    
    /**
     * Prepare on-device AI, storing models under `storage_dir`.
     *
     * The host owns the path — iOS Application Support, Android filesDir — so
     * nothing here hardcodes a platform location.
     */
    func aiInit(storageDir: String, insightKey: [UInt8]?) throws 
    
    /**
     * One stored insight in full, including its transcript.
     */
    func aiInsight(callId: String)  -> AiCallInsight?
    
    /**
     * Past insights, newest first. Empty when transcripts are not stored.
     */
    func aiInsights(limit: UInt32, offset: UInt32)  -> [AiInsightSummary]
    
    /**
     * Models this device could install, annotated with whether it can run them.
     */
    func aiModels()  -> [AiModel]
    
    /**
     * Begin capturing a call's audio for later transcription.
     *
     * Audio is tapped where it is decoded, so calling this does not move any
     * samples across this boundary. Safe to call mid-call.
     */
    func aiStartCapture(callId: String) throws 
    
    /**
     * Start downloading a model. Poll `ai_download_progress` for state.
     */
    func aiStartDownload(modelId: String) throws 
    
    /**
     * Stop capturing without transcribing.
     */
    func aiStopCapture(callId: String) 
    
    /**
     * Transcribe what was captured, and summarise it when an LLM is installed.
     *
     * Runs the models, so it takes seconds to minutes depending on call length
     * and device. Call it off the UI thread.
     */
    func aiTranscribe(callId: String) throws  -> AiCallInsight
    
    /**
     * Check if any active call was ended by the remote party.
     * Returns the call_id if detected, null otherwise.
     * The app should call this periodically from a UI timer (~2s).
     */
    func checkRemoteHangup()  -> String?
    
    /**
     * Get current call info, if any.
     */
    func getActiveCall()  -> CallInfo?
    
    /**
     * Get media statistics for a call.
     */
    func getMediaStats(callId: String)  -> MediaStats?
    
    /**
     * Get RX audio level for a call (0.0 = silence).
     */
    func getRxAudioLevel(callId: String)  -> Float
    
    /**
     * Get TX audio level for a call (0.0 = silence).
     */
    func getTxAudioLevel(callId: String)  -> Float
    
    /**
     * Process a push notification payload and retrieve the call offer.
     */
    func handlePushNotification(payload: PushCallPayload) throws  -> CallOffer
    
    /**
     * Hang up an active call.
     */
    func hangup(callId: String) throws 
    
    /**
     * Make an outgoing call directly via SIP.
     */
    func makeCall(uri: String, credentials: SipCredentials, preferredCodecs: [AudioCodec]) throws  -> CallInfo
    
    /**
     * Notify the core of a network connectivity change.
     * Call this from the platform when WiFi/cellular changes, or after reconnect.
     */
    func notifyNetworkChange() 
    
    /**
     * Register this device with the push gateway.
     * Returns device_id and auth token.
     */
    func registerDevice(registration: DeviceRegistration) throws  -> DeviceRegistrationResponse
    
    /**
     * Reject an incoming call.
     */
    func rejectIncomingCall(callToken: String) throws 
    
    /**
     * Send a DTMF digit.
     */
    func sendDtmf(callId: String, digit: String) throws 
    
    /**
     * Set the platform audio bridge for microphone/speaker I/O.
     */
    func setAudioBridge(bridge: PlatformAudioBridge) 
    
    /**
     * Set the preferred audio codec order.
     */
    func setCodecPreferences(codecs: [AudioCodec]) 
    
    /**
     * Set the event handler for receiving callbacks.
     */
    func setEventHandler(handler: MobileEventHandler) 
    
    /**
     * Set hold state.
     */
    func setHold(callId: String, onHold: Bool) throws 
    
    /**
     * Set mute state.
     */
    func setMute(callId: String, muted: Bool) throws 
    
    /**
     * Unregister this device from the push gateway.
     */
    func unregisterDevice(deviceId: String) throws 
    
    /**
     * Update the push token (e.g., after token refresh).
     */
    func updatePushToken(deviceId: String, newToken: String) throws 
    
}

