        self.port = port
        self.authUsername = authUsername
        self.displayName = displayName
    }
}



extension SipCredentials: Equatable, Hashable {
    public static func ==(lhs: SipCredentials, rhs: SipCredentials) -> Bool {
        if lhs.username != rhs.username {
            return false
        }
        if lhs.password != rhs.password {
            return false
        }
        if lhs.domain != rhs.domain {
            return false
        }
        if lhs.registrar != rhs.registrar {
            return false
        }
        if lhs.transport != rhs.transport {
            return false
        }
        if lhs.port != rhs.port {
            return false
        }
        if lhs.authUsername != rhs.authUsername {
            return false
        }
        if lhs.displayName != rhs.displayName {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(username)
        hasher.combine(password)
        hasher.combine(domain)
        hasher.combine(registrar)
        hasher.combine(transport)
        hasher.combine(port)
        hasher.combine(authUsername)
        hasher.combine(displayName)
    }
}


